
INSERT OR IGNORE INTO PostCategory (postId, categoryId) VALUES (2787, 34);

INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (2800, 'Công tử Bạc Liêu | Cuộc đời với SỰ TÍCH và GIAI THOẠI truyền kỳ', 'cong-tu-bac-lieu', '
<p>Công tử Bạc Liêu đốt tiền nấu trứng, tỏ ra mình giàu. Nghe danh Công tử Bạc Liêu chắc ai cũng từng nghe qua câu hát này. Ông là người có gia sản đồ sộ và ăn chơi đứng đầu bảng xếp hạng bấy giờ. Người ta bảo xứ Bạc Liêu trước đây 10 thửa ruộng thì 9 thửa là của nhà Công tử Bạc Liêu. Một phần còn lại là của dân thường và quan chức trong vùng. Vậy Công tử Bạc Liêu là ai? Tại sao Công tử Bạc Liêu lại nghèo?</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/công-tử-bạc-liêu-và-bà-ngô-thị-đen-1024x853.jpg" alt="Công tử Bạc Liêu và bà vợ Ngô Thị Đen" class="wp-image-3494"/><figcaption>Công tử Bạc Liêu và bà vợ Ngô Thị Đen</figcaption></figure>



<h2 class="wp-block-heading">Lịch sử Công tử Bạc Liêu</h2>



<p>Ông tên thật là Trần Trinh Huy (1900-1974). Ông còn có cái tên khác là Ba Huy (Ông là con trai thứ 3 trong nhà) hay Hắc công tử (Vì nước da đen của ông). Ông là một công tử ăn chơi khét tiếng miền Nam thập niên 30, 40 lúc bấy giờ.</p>



<h3 class="wp-block-heading">Người cha giàu có xuất thân từ cậu bé chăn trâu</h3>



<p>Cha Công tử Bạc Liêu là ông <a rel="noreferrer noopener" aria-label="Trần Trinh Trạch (mở trong tab mới)" href="https://vi.wikipedia.org/wiki/Tr%E1%BA%A7n_Trinh_Tr%E1%BA%A1ch" target="_blank">Trần Trinh Trạch</a> hay còn gọi là ông hội đồng Trạch xuất thân nghèo khó. Khi ấy ông Trạch là thằng ở trong một gia đình giàu có. Nhiệm vụ của ông là chăn trâu. Ông phải lo việc cho trâu ăn cỏ và sắp xếp chúng về chuồng đúng giờ.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/bàn-thờ-ông-trần-trinh-trạch-và-vợ-1024x853.jpg" alt="Bàn thờ ông Trần Trinh Trạch và vợ" class="wp-image-3486"/><figcaption>Bàn thờ ông Trần Trinh Trạch và vợ</figcaption></figure>



<p>Lúc bấy giờ, quân Pháp muốn mở rộng ảnh hưởng đến các địa chủ giàu có miền Nam lúc bấy giờ. Nên họ đã cho mở ra những phong trào bắt ép các phú hộ phải cho con em mình đến học các trường của Pháp dạy.</p>



<p>Với tư tưởng phong kiến của các địa chủ, phú hộ lúc bấy giờ. Họ không muốn cho con em họ học thứ văn hóa Tây phương đó. Họ cũng lo sợ người Pháp sẽ bắt con em họ làm con tin để uy hiếp. Nên thường họ lựa chọn cách là cho những người ở đợ trong nhà đi học thay cậu chủ của mình. Và ông Trạch &#8211; cậu bé chăn trâu thơ ngây lúc bấy giờ, là người được chọn học thay cho cậu chủ.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="850" src="https://media.huynhhieutravel.com/ảnh-gia-đình-công-tử-bạc-liêu-1024x850.jpg" alt="Hình ảnh gia đình Công tử Bạc Liêu" class="wp-image-3485"/><figcaption>Hình ảnh gia đình</figcaption></figure>



<p>Chuyện kể cậu bé chăn trâu Trạch lúc ấy lo sợ, khóc rống lên vì sợ hãi. Ông năn nỉ được ở lại chăn trâu nhưng gia đình chủ không cho phép. Họ bắt ông đi học cho bằng được. Nhưng nhờ vậy, cuộc đời cậu bé chăn trâu Trạch đã đổi thay. Nhờ sự chăm chỉ, thông minh của một cậu bé nhà nghèo, ông Trạch học hành giỏi giang. Sau đó xin được một chân thư ký ở ủy ban tỉnh Bạc Liêu lúc bấy giờ.</p>



<h3 class="wp-block-heading">Từ thầy ký Trạch trở thành một ông hội đồng Trạch giàu có</h3>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/tách-trà-cổ-từ-thời-nhà-thanh-của-công-tử-bạc-liêu-1024x853.jpg" alt="Tách trà cổ" class="wp-image-3513"/><figcaption>Tách trà cổ</figcaption></figure>



<p>Lúc bấy giờ, nhờ làm việc ủy ban tỉnh Bạc Liêu nên ông thường hay tiếp xúc cùng những phú hộ giàu có. Ông vừa thông minh, lại siêng năng, phóng khoáng giúp đỡ nhiều phú hộ về đóng thuế tô đất. Ông bắt đầu được ông bá hộ Phan Văn Bì &#8211; cũng là bá hộ giàu có bấy giờ, để ý đến.</p>



<p>Ông Bì tạo điều kiện cho thầy ký Trạch làm quen con gái của mình. Khi thấy cả hai hợp ý, ông đã gả con gái cho ông Trạch và chia một số đất đai, gia sản để ông quản lý. Ông Trạch nghỉ việc thư kỷ ở ủy ban về quản lý gia sản được giao cho.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/nhà-cổ-công-tử-bạc-liêu-1024x853.jpg" alt="Nhà cổ Công tử Bạc Liêu" class="wp-image-3506"/><figcaption>Nhà cổ Công tử Bạc Liêu</figcaption></figure>



<p>Với đầu óc của một người có học và thông minh, ông Trạch nhanh chóng vươn lên, mở rộng gia sản của mình hơn nữa. Không những giỏi việc quản lý đất đai, ông Trạch còn mở rộng kinh doanh theo nhiều hướng mới. Ông còn xin được độc quyền cả việc cầm đồ. Lúc bấy giờ, thuật ngữ cầm đồ khá mới mẻ.</p>



<p>Sau này, ngay cả chính những người anh em rể của ông Trạch vì ham mê cờ bạc. Họ cũng mất dần gia sản vào tay ông. Ông bá hộ Bì trước khi chết cũng ngậm ngùi tự an ủi rằng: ít ra, gia sản của mình cũng không rơi hết vào tay người ngoài mà là vào tay con rể và con gái.</p>



<p>Theo thống kê, ngoài những gia sản khác, ông bá hộ Trạch lúc bấy giờ sở hữu 74 sở điền lớn, 110.000 ha ruộng lúa và 100.000 ha ruộng muối.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/đồ-dùng-tinh-xảo-nhà-công-tử-bạc-liêu-1024x853.jpg" alt="Đồ dùng tinh xảo" class="wp-image-3495"/><figcaption>Đồ dùng tinh xảo</figcaption></figure>



<h3 class="wp-block-heading">Cậu ba Huy đi du học và sự kỳ vọng lớn lao</h3>



<p>Ông hội đồng Trạch là người có ăn học cộng với sự từng trải nhiều biến cố. Ông hiểu thế nào nếu con của mình không quản lý tài sản của mình tốt. Ông nhận thấy dù mình giàu như ba vợ thì cũng có ngày gia sản có thể mất hết do con cái.</p>



<p>Khi ấy, ông kỳ vọng vào con trai thứ ba của mình là cậu Trần Trinh Huy. Một chàng trai trẻ thông minh, học hành giỏi giang. Ông đưa con mình sang Pháp du học. Mong rằng con mình sẽ học rộng thành tài, về quản lý gia sản của mình.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="1024" src="https://media.huynhhieutravel.com/bình-sứ-cổ-nhà-công-tử-bạc-liêu-1024x1024.jpg" alt="Bình sứ cổ nhà Công tử Bạc Liêu" class="wp-image-3487" srcset="https://media.huynhhieutravel.com/bình-sứ-cổ-nhà-công-tử-bạc-liêu-1024x1024.jpg 1024w, https://media.huynhhieutravel.com/bình-sứ-cổ-nhà-công-tử-bạc-liêu-150x150.jpg 150w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Bình sứ cổ</figcaption></figure>



<p>Tuy vậy, khi sang Pháp du học, cậu ba Huy lại giỏi nhiều thứ khác hơn là chuyện đi học. Cậu học đủ các bằng thời thượng lúc bấy giờ: bằng nhảy đầm, bằng láy xe hơi, bằng láy xe máy, bằng láy máy bay,&#8230; Cậu ba Huy sang Pháp chỉ thường đi nông trường học hỏi kỹ thuật, cách quản lý của họ. Ngoài ra, thời gian còn lại cậu chỉ lo vào việc vui chơi. Cậu còn cưới một người vợ Tây bên Pháp và có một người con.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/giường-công-tử-bạc-liêu-1024x853.jpg" alt="Giường Công tử Bạc Liêu" class="wp-image-3496"/><figcaption>Giường Công tử Bạc Liêu</figcaption></figure>



<h3 class="wp-block-heading">Cậu ba Huy về nước và truyền kỳ công tử Bạc Liêu bắt đầu</h3>



<p>Cuối năm 1926, chàng trai 26 tuổi Trần Trinh Huy kết thúc chuyến du học về nước với bao điều thú vị sắp sửa mở ra. Nghe tin con mình về nước, ông hội đồng Trạch vui mừng thân chinh cùng vợ mình lên Sài Gòn đón cậu ba về.</p>



<p>Tương truyền, khi lên Sài Gòn, ông hội đồng Trạch cầm túi xách nhà quê, mặc áo bà bà và mang đôi dép lào vào tiệm bán xe hơi sang trọng nhất Sài thành lúc bấy giờ. Ban đầu, người nhân viên ở đây cười cái chất nhà quê lôi thôi của ông già xách giỏ xách lựa xe hơi này.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/xe-cổ-công-tử-bạc-liêu-1024x853.jpg" alt="Xe cổ của Công tử Bạc Liêu" class="wp-image-3514"/><figcaption>Xe cổ của Công tử Bạc Liêu</figcaption></figure>



<p>Nhưng khi ông hội đồng Trạch bảo lấy xe hơi đời mới nhất, mắc nhất là chiếc Peugeot hiện đại lúc bấy giờ ra. Ông hội đồng Trạch cầm giỏ xách mở ra những cọc tiền mặt làm cho người nhân viên bán xe phải trố mắt nhìn.</p>



<p>Cậu ba Huy khi gặp cha mình đã lập tức trổ tài lái xe của mình. Ông láy xe với vận tốc gần 100km/h từ Sài Gòn về Bạc Liêu. Ông hội đồng Trạch lúc đó mở tiệc lớn chiêu đãi tất cả mọi người. Lúc ấy, hàng nghìn vị khách là quan lớn, bá hộ giàu có lúc tỉnh Nam kỳ đều đến dự tiệc chúc mừng.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="880" src="https://media.huynhhieutravel.com/hành-lang-nhà-công-tử-bạc-liêu-1024x880.jpg" alt="Hành lang nhà Công tử Bạc Liêu" class="wp-image-3497"/><figcaption>Hành lang nhà Công tử Bạc Liêu</figcaption></figure>



<h3 class="wp-block-heading">Tài trí của Công tử Bạc Liêu</h3>



<p>Ông tuy nổi tiếng về sự ăn chơi của mình, nhưng ông cũng rất tài tình và học rộng biết nhiều. Ông hội đồng Trạch là người có ăn học, lại làm ăn lâu năm. Ông không đơn giản giao toàn bộ tài sản của mình cho đứa ăn chơi phá của quản lý.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/bộ-bàn-ghế-của-công-tử-bạc-liêu-1024x853.jpg" alt="Bộ bàn ghế" class="wp-image-3488"/><figcaption>Bộ bàn ghế</figcaption></figure>



<h4 class="wp-block-heading">Quản lý tài sản như người Tây</h4>



<p>Khi nghe cha mình muốn giao toàn bộ tài sản để ông quản lý. Cậu ba Huy đã giao kèo với ba mình rằng mọi tài sản phải được ông toàn quyền quản lý. Ông hội đồng Trạch không được phép xen vào và phải tuân thủ quy trình quản lý. Mọi thu chi đều phải có sổ sách rõ ràng. Ngay cả khi lấy tiền, ông hội đồng Trạch cũng phải xin phép cậu ba Huy.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/khách-tham-quan-nhà-công-tử-bạc-liêu-1024x853.jpg" alt="Khách tham quan nhà Công tử Bạc Liêu" class="wp-image-3499"/><figcaption>Khách tham quan nhà Công tử Bạc Liêu</figcaption></figure>



<h4 class="wp-block-heading">Mở ngân hàng đầu tiên Việt Nam</h4>



<p>Cậu ba Huy cũng là người đề xuất cha mình mở ngân hàng đầu tiên ở Việt Nam. Ngân hàng được mở ra, nhiều bá hộ giàu có đều góp vốn và gửi tiền vào đó.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/bộ-bàn-ghế-nhà-công-tử-bạc-liêu-1024x853.jpg" alt="Bộ bàn ghế nhà Công tử Bạc Liêu" class="wp-image-3489"/><figcaption>Bộ bàn ghế nhà Công tử Bạc Liêu</figcaption></figure>



<h4 class="wp-block-heading">Thuê chuyên gia Pháp quản lý tài sản cho mình</h4>



<p>Ông biết rằng với gia sản đồ sộ của gia đình, ông không đủ khả năng và trình độ quản lý toàn bộ chúng. Ông cũng sợ mất thời gian vào công việc và bỏ lỡ việc ăn chơi của mình. Sẽ rất có tội nếu có tiền mà bạn không biết sử dụng chúng mà bị chúng chi phối. Vì thế ông cho thuê một quản lý có tiếng người Pháp là ông Henry. Ông Henry ban đầu từ chối nhưng với số hoa hồng 10% lợi nhuận hàng năm hấp dẫn ông đã nhận lời.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/không-gian-nhà-công-tử-bạc-liêu-1024x853.jpg" alt="Không gian nhà Công tử Bạc Liêu" class="wp-image-3500"/><figcaption>Không gian nhà Công tử Bạc Liêu</figcaption></figure>



<h4 class="wp-block-heading">Mở đầu những thứ mới mẻ ở Việt Nam</h4>



<p>Khi du học ở nước ngoài về, tư tưởng mới mẻ trong đầu Công tử Bạc Liêu luôn rất tiến bộ. Ông là người rất coi trọng việc bình đẳng nam nữ. Ông muốn con gái cũng phải có ăn học, biết ra ngoài xã hội làm việc. Ông là người đầu tiên tổ chức các cuộc thi hoa hậu miệt vườn ở miền Nam lúc bấy giờ. Tuy rằng, lúc đó ông cũng chọn ra các cô nhân tình của mình từ những thí sinh đi thi.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/bộ-đèn-cổ-nhà-công-tử-bạc-liêu-1024x853.jpg" alt="Bộ đèn cổ nhà Công tử Bạc Liêu" class="wp-image-3490"/><figcaption>Bộ đèn cổ nhà Công tử Bạc Liêu</figcaption></figure>



<p>Ông cũng là người tư vấn các quan trưởng mở các hội chợ ở các làng quê Việt Nam. Những buổi hội chợ là những ngày buôn bán tấp nập hàng hóa. Những thương gia, nông dân cùng nhau trẫy hội, mua sắm, vui chơi.</p>



<h4 class="wp-block-heading">Người lấy gốc là nông dân</h4>



<p>Một lần trong bữa ăn, ông hỏi cha mình rằng: Cha có biết nhà mình giàu là do đâu không? Ông hội đồng Trạch bất ngờ và trả lời rằng: Là do mình làm ăn tích cóp, mở rộng mua bán, ruộng lúa bạt ngàn. ông mới mỉm cười trả lời: Cha sai rồi, nhà mình giàu là do tá điền. Chính họ là người trông coi ruộng đất, nộp tô thuế hàng năm cho chúng ta.</p>



<p>Ông luôn coi trọng nhưng người nông dân, tá điền làm việc cho nhà mình. Hàng năm vào dịp lễ Tết, ông thường tổ chức phát tiền, lễ hội. Ông cũng thường làm lễ xóa nợ cho người tá điền nợ tiền mình.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="863" src="https://media.huynhhieutravel.com/bộ-tủ-bàn-ghế-nhà-công-tử-bạc-liêu-1024x863.jpg" alt="Bộ tủ bàn ghế" class="wp-image-3491"/><figcaption>Bộ tủ bàn ghế</figcaption></figure>



<h4 class="wp-block-heading">Mua máy bay để làm ruộng</h4>



<p>Công tử Bạc Liêu từng sở hữu chiếc máy bay tư nhân đầu tiên Việt Nam với nhiều truyền kỳ. Nhưng chuyện kể lại ông mua máy bay là để&#8230; làm ruộng. Trước đây, nạn châu chấu ăn ruộng lúa thường hoành hành. Có những lúc, châu chấu bay đen nghẹt cả bầu trời. Người dân không thể nào ứng cứu kịp thời những đồng lúa bị nạn châu chấu lướt qua.</p>



<p>Ruộng lúa của ông lúc bấy giờ lại bạt ngàn mênh mông. Để ứng cứu và chăm coi ruộng lúa tốt hơn, vừa thể hiện đẳng cấp ăn chơi của mình với bằng láy máy bay học bên Pháp. Với đầy đủ các lý do, ông đã đặt mua một chiếc máy bay về để làm ruộng. Chiếc máy bay lúc đó tương truyền được mua với giá 100kg vàng.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="916" src="https://media.huynhhieutravel.com/căn-phòng-nhà-công-tử-bạc-liêu-1024x916.jpg" alt="Căn phòng dần hư hao theo thời gian" class="wp-image-3492"/><figcaption>Căn phòng dần hư hao theo thời gian</figcaption></figure>



<h3 class="wp-block-heading">Những người vợ của Công tử Bạc Liêu</h3>



<p>Ông có 3 người vợ chính thức và tương truyền có đến hàng trăm người tình bên ngoài. Người vợ đầu của ông là bà Ngô Thị Đen &#8211; người con gái đẹp nhất xứ Bạc Liêu lúc bấy giờ. Người vợ hai là con một phú hộ giàu có ở Mỹ Tho là bà Nguyễn Thị Hai. Người vợ thứ ba là con thứ ba của người sửa xe đạp cũng có cái tên là Ba.</p>



<p>Đặc biệt, khi du học ở bên Pháp, ông còn có một người vợ không chính thức là người Tây. Cô Tây ấy tên là Marie, một nhân viên thu ngân ở Pháp.&nbsp; Hai người ở với nhau và có một người con trai tên là Richard, sau này trở thành phi công. Nhưng do khác biệt văn hóa, khi về nước ông để hai mẹ con ở lại Paris và về nước.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/chiếc-ghế-được-chạm-trổ-xà-cừ-tỉ-mỉ-1024x853.jpg" alt="Chiếc ghế được chạm trổ xà cừ tỉ mỉ" class="wp-image-3493"/><figcaption>Chiếc ghế được chạm trổ xà cừ tỉ mỉ</figcaption></figure>



<p>Ngoài ra, ông còn có hàng chục người con bên ngoài khác nhau. Tuy dòng họ Trần Trinh không chấp nhận những người vợ ngoài của Công tử Bạc Liêu. Nhưng những người con đều được liệt vào gia phả và phân chia tài sản.</p>



<h3 class="wp-block-heading">Sự khánh kiệt của Công tử Bạc Liêu &#8211; Sự tàn lụi gia tộc Trần Trinh</h3>



<p>Giàu có là thế, ăn chơi khét tiếng là thế nhưng ông về già cũng khó khăn và gia sản gia tộc Trần Trinh cũng bị khánh kiệt dần. Người ta đồn thổi nói rằng Công tử Bạc Liêu do ăn chơi mà trở nên phá sản.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/máy-akai-cổ-nhà-công-tử-bạc-liêu-1024x853.jpg" alt="Máy akai cổ" class="wp-image-3501"/><figcaption>Máy akai cổ</figcaption></figure>



<p>Nhưng cũng không hẳn là thế. Một người có ăn học, gia sản lớn nhất Nam kỳ lúc bấy giờ. Dù có ăn chơi cũng không thể nào phá hết được. Lý do thật sự là do năm 1960, cách mạng cải cách ruộng đất bắt đầu. Nhưng tài sản ruộng đất bạt ngàn của gia tộc Trần Trinh đều bị tịch thu. Ngoài ra, ngân hàng và những tài sản lớn của ông đều bị chính phủ kê biên sau khi cách mạng nổ ra.</p>



<p>Những gia sản còn sót lại chỉ là những căn nhà mặt phố ở Sài Gòn và những tài sản kịp đem ra nước ngoài. Vì vậy, sau này những người con của ông đều bán nhà ra nước ngoài. Chỉ còn lại một người con tên Đức ở lại Việt Nam. Nhưng cũng lâm vào cảnh bần hàn do nhiều nguyên nhân.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/hương-khói-luôn-nghi-ngút-từ-khách-tham-quan-cúng-viếng-1024x853.jpg" alt="Hương khói luôn nghi ngút từ khách tham quan cúng viếng" class="wp-image-3498"/><figcaption>Hương khói luôn nghi ngút từ khách tham quan cúng viếng</figcaption></figure>



<h2 class="wp-block-heading">Sự tích Công tử Bạc Liêu</h2>



<p>Ông tuy đã mất được nhiêu năm nhưng những sự tích của ông vẫn còn lưu truyền đến ngày nay. Đến nay, chưa ai có thể hơn được ông về độ chịu chơi cũng như tài sản có được.</p>



<h3 class="wp-block-heading">Chuyên gia Muay Thái</h3>



<p>Ông là người mê võ. Ông muốn học võ để nâng cao khí phách của một người anh đàn ông anh hào. Ông không theo học những loại võ vẽ vời hay nâng cao thể chất. Mà ông lựa chọn Muay Thái với những kỹ thuật đối kháng cao. Ông từng phải cất công qua Thái Lan thuê thầy võ thượng hạng về. Ông cùng với em gái út của mình là bà Tám Bò cùng học thấy Thái về võ Muay. Không phải ai cũng biết ông là một võ sư Muay Thái thượng thừa.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="1024" src="https://media.huynhhieutravel.com/máy-hát-thời-xưa-nhà-công-tử-bạc-liêu-1024x1024.jpg" alt="Máy hát thời xưa" class="wp-image-3502" srcset="https://media.huynhhieutravel.com/máy-hát-thời-xưa-nhà-công-tử-bạc-liêu-1024x1024.jpg 1024w, https://media.huynhhieutravel.com/máy-hát-thời-xưa-nhà-công-tử-bạc-liêu-150x150.jpg 150w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Máy hát thời xưa</figcaption></figure>



<h3 class="wp-block-heading">Hắc Bạch công tử</h3>



<p>Hắc Bạch công tử là tên gọi để phân biệt hai vị công tử ăn chơi có tiếng ở Sài thành lúc bấy giờ. <a href="https://vietnamnet.vn/vn/doi-song/song-la/cuoc-doi-george-le-cong-phuoc-300853.html" target="_blank" rel="noreferrer noopener nofollow" aria-label="George Phước (mở trong tab mới)">George Phước</a> là một công tử ở Mỹ Tho với nước gia trắng, nên được xưng là Bạch công tử. Còn Công tử Bạc Liêu với nước da ngâm đen nên được xưng là Hắc công tử để phân biệt.</p>



<h3 class="wp-block-heading">Giao tranh giữa Hắc Bạch công tử</h3>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow"><p><em>Đang lúc cô Ba Trà, một người con gái có sắc đẹp làm xao xuyến tâm hồn Bạch công tử, thua bài sạch túi, ông trưởng giả lớn tuổi chưa kịp cung phụng tiền bạc tiếp để vừa lòng mỹ nhân, Bạch Công tử lù lù lái xe lại nhà cô Ba Trà, rủ xuống Cần Thơ ăn cá cháy và đánh bài gỡ bạc.</em></p><p><em>Hai người vừa xuống đến quán Bungalows ở Cần Thơ, máy xe chưa nguội thì chiếc Sport tám máy của Hắc Công Tử cũng vừa tới, thắng cái két. Cả hai lâm vào cảnh khó xử, việc chiếm được mỹ nhân chỉ còn cậy vào tài chinh phục của bản thân mình.</em></p><p><em>Cả ba cùng đưa nhau vào khách sạn. Bạch Công tử lột chiếc cà rá hột xoàn trị giá 3.000 đồng vào thời đó để trên bàn trước khi vào phòng tắm. Lúc trở ra, thấy cô Ba Trà đeo thử nó trên tay, Bạch Công tử liền lên tiếng tặng luôn. Sau đó Hắc Công tử đã mua tặng cô Ba Trà một chiếc nhẫn trị giá gấp đôi.</em></p><cite>Trích tác giả Nguyễn Thiện</cite></blockquote>



<h3 class="wp-block-heading">Công tử Bạc Liêu đốt tiền có thật không</h3>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/một-góc-nhà-công-tử-bạc-liêu-1024x853.jpg" alt="Một góc nhà Công tử Bạc Liêu" class="wp-image-3503"/><figcaption>Một góc nhà Công tử Bạc Liêu</figcaption></figure>



<p>Chuyện kể Bạch công tử mở một gánh hát cải lương. Ông thường hay mời kỳ phùng địch thủ vừa là bạn thân của mình là Hắc công tử đến nghe. Một hôm khi đang nghe cải lương ở gánh hát, Bạch công tử vô tình làm rớt từ tiền 5 trị giá đồng đông dương xuống đất. Ông bèn cuối xuống tìm, vì đèn trong rạp hát khá tối nên tìm mãi chưa thấy. Hắc công tử thấy cơ hội hạ nhục đối phương đã đến. Ông bèn lấy bật lửa đốt tờ tiền đông dương 100 đồng bạc soi cho Bạch công tử tìm tiền.</p>



<p>Sau khi tìm được tờ 5 đồng. Hắc công tử nói nhỏ với Bạch công tử rằng: &#8220;Anh có biết, vì tìm tờ 5 đồng của anh mà tôi đã đốt mất hết 3 tờ 100 đồng đông dương không?&#8221;.</p>



<p>Bị một vố quá đau, Bạch công tử đã hẹn với Bạch công tử thi thố nầu chè đậu xanh bằng cách đốt tiền xem ai sẽ thắng. Ta thường nghe <a rel="noreferrer noopener nofollow" aria-label="câu hát (mở trong tab mới)" href="https://www.nhaccuatui.com/bai-hat/bac-lieu-hoai-co-phi-nhung.ccnfYbwdfJ.html" target="_blank">câu hát</a> &#8220;Nghe danh công tử Bạc Liêu đốt tiền nấu trứng&#8230;&#8221;. Nhưng thật sự cuộc thi được tổ chức là nấu chè đậu xanh. Bài hát có từ nấu trứng chỉ để cho vần dễ hát mà thôi.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/một-số-vật-cổ-nhà-công-tử-bạc-liêu-1024x853.jpg" alt="Một số vật cổ nhà Công tử Bạc Liêu" class="wp-image-3504"/><figcaption>Một số vật cổ nhà Công tử Bạc Liêu</figcaption></figure>



<p>Trong cuộc thi, vì chỉ dùng tờ tiền nước ngoài là polyme khó cháy so với tiền giấy trong nước của Bạch Công Tử. Nên Hắc công tử đã thua. Nhưng cuộc thi đó cũng chứng tỏ sự giàu có và chịu chơi của hai vị công tử giàu nhất xứ Nam kỳ lúc bấy giờ.</p>



<p>Tuy vậy, sau này ông Đức &#8211; người con của Công tử Bạc Liêu, nói rằng đó chỉ là lời đồn thổi. Vì vậy, ta cũng chỉ có thể nói đây là một sự tích thú vị giữa chứ không chứng thực được.</p>



<h3 class="wp-block-heading">Vua Bảo Đại có gì là Công tử Bạc Liêu có cái đó</h3>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/nội-thất-nhà-công-tử-bạc-liêu-1024x853.jpg" alt="Nội thất nhà Công tử Bạc Liêu" class="wp-image-3509"/><figcaption>Nội thất nhà Công tử Bạc Liêu</figcaption></figure>



<p>Khi ấy để nói sự giàu có, chịu chơi của ông người ta có câu: &#8220;Vua Bảo Đại có những gì là Công tử Bạc Liêu có cái đó, nhưng Công tử Bạc Liêu có gì chưa chắc vua Bảo Đại đã có&#8221;.</p>



<p>Ông có hai chiếc xe là Ford Vedette dùng để thăm ruộng và chiếc Peugeot dùng để đi chơi. Lúc bấy giờ cả miền Nam chỉ có hai chiếc là của Công tử Bạc Liêu và vua Bảo Đại. Ông cũng là người đầu tiên sở hữu chiếc máy bay tư nhân đầu tiên Việt Nam. Vua Bảo Đại cũng có một chiếc nhưng đó là tài sản quốc hữu.</p>



<p>Trên nhà ông ở Bạc Liêu có hẳn một căn gác đón nắng. Người ta thường bảo ông cho gia nhân đem tiền lên đó phơi vào dịp nắng tốt. Tránh cho tiền bị nấm mốc, hư hỏng.</p>



<p>Thỉnh thoảng, ông lại tổ chức những bữa tiệc lớn với rượu và sâm banh hảo hạng cùng những người quyền quý. Đôi khi trong lúc đánh bạc, ông thua đến 30.000 đồng đông dương. Lúc bấy giờ 1kg lúa chỉ có giá chưa đến 0,1 đồng đông dương.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="920" src="https://media.huynhhieutravel.com/phòng-khách-nhà-công-tử-bạc-liêu-1024x920.jpg" alt="Phòng khách nhà Công tử Bạc Liêu" class="wp-image-3511"/><figcaption>Phòng khách nhà Công tử Bạc Liêu</figcaption></figure>



<p>Ông thường di chuyển nghỉ mát ở Vũng Tàu, Hà Tiên, Cần Thơ và Đà Lạt. Mỗi nơi ông đều có những căn biệt thự riêng ở vị trí trung tâm để tiện di chuyển. Nhưng ông cũng rất ít khi ở những biệt thự đó mà thường thuê những khách sạn đắt tiền sang trọng ở ngoài.</p>



<p>Khi di chuyển, ông thường mang theo cả đoàn tùy tùng để và trang bị cá nhân. Từ mắt kính, quần áo, gậy đến những bộ comple đắt tiền. Ngoài ra, còn đem theo cả những chú chó cưng của mình trong chuyến du lịch.</p>



<h3 class="wp-block-heading">Đổi nhà phố lấy người đẹp</h3>



<p>Bà Bùi Thị Ba là người vợ ba của Công tử Bạc Liêu cũng là người vợ chính thức cuối cùng của ông khi về già. Lúc đó khi ông đang tập thể dục trên sân thượng nhà mình ở Sài Gòn, ông vô tình thấy một cô gái gánh nước xinh đẹp. Nắng sáng chiếu rọi vào từng giọt mồ hôi trên mặt cô gái rơi xuống. Người con gái mặc áo bà bà, vừa thanh tao vừa lam lũ đã hớp hồn Công tử Bạc Liêu ngay lập tức.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/người-vợ-thứ-ba-của-công-tử-bạc-liêu-1024x853.jpg" alt="Người vợ thứ ba của Công tử Bạc Liêu" class="wp-image-3505"/><figcaption>Người vợ thứ ba của Công tử Bạc Liêu</figcaption></figure>



<p>Sau khi cho người điều tra, ông biết được đó là một người con gái của người thợ sửa xe đạp gần đó. Ông ngay lập tức tìm đến nhà của người đó, xin phép gã con gái cho mình. Ông mong đem người con gái đó về làm vợ dù đổi bất cứ giá nào. Dù đó là căn nhà mặt phố ông đang ở đi nữa.</p>



<h3 class="wp-block-heading">Giường Công tử Bạc Liêu giá trị ra sao</h3>



<p>Công tử Bạc Liêu có nhiều phòng ngủ, mỗi phòng ông đều có những chiếc giường đặc biệt làm bằng gỗ sưa. Giường ngủ nhà ông có hai loại: một giành cho mùa hè và một giành cho mùa đông.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/phòng-công-tử-bạc-liêu-1024x853.jpg" alt="Phòng Công tử Bạc Liêu" class="wp-image-3510"/><figcaption>Phòng Công tử Bạc Liêu</figcaption></figure>



<p>Giường mùa hè có lót 1 phiến đá cẩm thạch ở giữa giúp cho luôn thoáng mát vào mùa hè khi nằm ở trên. Giường mùa đông thì ấm áp, giữ ấm cho cơ thể rất tốt. Tất cả giường đều được đóng bằng gỗ cây sưa. </p>



<p>Gỗ sưa là loại khá mắc tiền, đôi khi có tiền cũng kiếm không ra để mua. Gỗ sưa vừa tốt vừa thơm, điều đặc biệt làm nên giá trị của nó chính là công dụng trừ tà của nó. Gỗ sưa còn đặc biệt tốt trong phong thủy.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="892" src="https://media.huynhhieutravel.com/sự-cổ-kính-nhà-công-tử-bạc-liêu-1024x892.jpg" alt="Sự cổ kính ở ngôi nhà" class="wp-image-3512"/><figcaption>Sự cổ kính của ngôi nhà</figcaption></figure>



<p>Khi nhắc về Công tử Bạc Liêu, người ta nghĩ ngay đến vị Công tử ăn chơi trác tán. Nhưng thật chất đôi khi do sự truyền miệng của người đời mà sai lệch đi.</p>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow"><p> “Để giúp đỡ 7 người xe kéo này, ba tôi đã không cho tiền như kiểu bố thí cho họ mà ông đã gọi tất cả 7 người xe kéo lại và bảo mỗi xe chở một món đồ cho ông để đến hội chợ. Ba tôi ngồi một xe, xe kế cho vệ sĩ, xe thứ ba cho người cháu, vẫn còn bốn xe đang chờ ông chưa biết chở gì, thấy vậy ba tôi liền bỏ mũ đặt lên xe thứ 4, xe thứ 5 chở gậy ba – toong, xe thứ sáu chở cái cặp da, thấy còn con chó Nhật vẫn đang lẽo đẽo chạy theo ông liền đặt chú chó này lên chiếc xe kéo thứ 7. Cả 7 chiếc xe kéo đến Hội chợ. </p><p>Chuyện xuất phát từ tình thương của ba tôi với người nghèo, thế mà trở thành câu chuyện ba tôi – Công tử Bạc Liêu thừa tiền, nhiều tiền quá, tiêu không hết nên bày ra việc chơi ngông gọi một lúc gần chục xe kéo để chở chó, chở gậy, chở cái cặp da”</p><p></p><cite>Ông Đức &#8211; Con của Công tử Bạc Liêu, nói.</cite></blockquote>



<h2 class="wp-block-heading">Tham quan nhà Công tử Bạc Liêu</h2>



<p>Nhà Công tử Bạc Liêu là một trong ba ngôi nhà cổ nổi tiếng còn nguyên vẹn đến nay. Nó đã có gần 100 năm tuổi nhưng kiến trúc bên trong vẫn còn khá nguyên vẹn. Nó đại diện cho văn hóa nhà cổ của những bá hộ ngày xưa ở miền Tây Nam bộ. Hiện nay, nhà Công tử Bạc Liêu trực thuộc Văn phòng Tỉnh ủy Bạc Liêu.</p>



<p>Tham khảo thêm du lịch Bạc Liêu về địa điểm, cách đi và review chi tiết tại đây: <a rel="noreferrer noopener" aria-label="https://huynhhieutravel.com/du-lich-bac-lieu (mở trong tab mới)" href="https://huynhhieutravel.com/du-lich-bac-lieu" target="_blank">https://huynhhieutravel.com/du-lich-bac-lieu</a></p>



<h3 class="wp-block-heading">Nhà cổ Công tử Bạc Liêu</h3>



<p>Ngôi nhà Công tử Bạc Liêu này được xây dựng từ năm 1919. Tất cả kiến trúc đều do kỹ sư Pháp thiết kế và được thầy phong thủy tốt nhất Việt Nam lúc bấy giờ điều chỉnh thêm. Toàn bộ vật dụng từ thép, gạch đến những vật phẩm nội thất đều được chuyển từ Pháp sang. </p>



<p>Vì vậy, các vật dụng trong nhà của Công tử Bạc Liêu hiện nay đều có chữ P chìm trên đó. Chữ P đó viết tắt cho từ Paris để chứng minh nó xuất xứ từ Paris hoa lệ.Tất cả giá trị vật dụng trong nhà được định giá khoảng hơn 400 tỷ đồng. </p>



<h3 class="wp-block-heading">Nhà Công tử Bạc Liêu hiện nay </h3>



<p>Ngôi nhà theo đầy đủ tiêu chuẩn vị trí tốt nhất thời bấy giờ. Vừa gần chợ, gần sông và gần lộ lớn. Người dân vẫn thường gọi đây là nhà lớn. Kiến trúc ngôi nhà Công tử Bạc Liêu hiện nay gồm hai tầng.</p>



<p>Tầng dưới có một phòng khách sang trọng và thoáng mát. Bên trong là hai căn phòng ngủ. Phòng ngủ của ông hội đồng Trạch và phòng ngủ của Công tử Bạc Liêu. Phía sau là căn phòng ăn của gia đình.</p>



<p>Phòng ngủ vẫn còn trưng bày hai chiếc giường của Công tử Bạc Liêu. Riêng ở phòng Công tử Bạc Liêu còn có bộ bàn trang điểm riêng. Công tử Bạc Liêu là người rất chú trọng về nhan sắc của mình. Khi ra đường ông thường phải chỉnh chu toàn bộ bề ngoài mình.</p>



<p>Tầng trên có 3 phòng ngủ và hai đại sảnh. Mỗi nơi đều có những vật trang trí, bàn ghế đều sang trọng và tỉ mỉ. Màu chủ đạo căn nhà là màu vàng đen và trắng. Căn phòng vào ban ngày, ánh nắng tràn ngập sinh khí. Còn buổi tối, khi thắp đèn vàng lên, nó lung linh sang trọng vô cùng, rực rỡ cả căn phòng.</p>



<p>Ở ban công, khi nhìn ra là con sông cùng cây cầu bắt ngang qua. Cảnh con đò, dòng sông và dòng người đông đúc khiến ta thích thú khi nhìn ngắm. Tuy vậy, ngôi nhà lớn này không phải hoàn toàn là nhà Công tử Bạc Liêu mà nó chỉ là một bộ phận thôi. Nhà Công tử Bạc Liêu là một dãy nhà rộng lớn hơn nhiều. Tuy vậy, nó hiện đang được trưng dụng làm Khách sạn Công tử Bạc Liêu. Vậy nhà Công tử Bạc Liêu ở đâu?</p>



<h3 class="wp-block-heading">Địa chỉ nhà Công tử Bạc Liêu</h3>



<p>Địa chỉ: 13 Điện Biên Phủ, Phường 3, Bạc Liêu, Việt Nam.</p>



<figure><iframe src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d5568.522040351096!2d105.71964805866119!3d9.285354798276206!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31a1097cb46afa5f%3A0x8fe07c6bb13c1af3!2zTmjDoCBDw7RuZyBU4butIELhuqFjIExpw6p1!5e0!3m2!1svi!2s!4v1545489060906" width="600" height="450" allowfullscreen=""></iframe></figure>



<h3 class="wp-block-heading">Vé tham quan nhà Công tử Bạc Liêu</h3>



<p>Giá vé tham quan nhà Công tử Bạc Liêu: 20.000đ/khách. Vé đã bao gồm người thuyết minh. Tuy vậy, người thuyết minh sẽ không thuyết minh từng người mà chờ đông đủ mới thuyết minh một lượt. Bạn nên chờ nếu muốn nghe hết phần thuyết minh khi thăm nhà Công tử Bạc Liêu.</p>



<h2 class="wp-block-heading">Khách sạn Công tử Bạc Liêu</h2>



<p>Khách sạn Công tử Bạc Liêu được nằm trên tòa nhà cũ trước đây của Công tử Bạc Liêu. Nó vẫn còn giữ nguyên một số trang trí nhà cũ còn lại. Vì vậy, nó vừa có phần hiện đại vừa có phần cổ kính trong kiến trúc.</p>



<p>Đặc biệt, nơi đó còn có dịch vụ khá hay như hát với nhau vào mỗi tối. Bạn có thể đặt những ca khúc mình muốn hát. Ngoài ra, bạn có thể nghe nhiều làn điệu dân ca và vọng cổ khi đến đây.</p>



<h3 class="wp-block-heading">Nhà hàng Công tử Bạc Liêu</h3>



<p>Nơi đây cũng phục vụ nhiều món ăn khá ổn cho việc ăn sáng cũng như các bữa ăn chính: Bánh tằm Ngan Dừa, bún cá công tử, gỏi cá lóc trộn bầu, lẩu công tử,&#8230;</p>



<h3 class="wp-block-heading">Số điện thoại khách sạn Công tử Bạc Liêu</h3>



<p><strong>Số điện thoại</strong>: +842913953304</p>



<h3 class="wp-block-heading">Giá phòng khách sạn Công tử Bạc Liêu</h3>



<ul class="wp-block-list"><li>Phòng VIP 1: 2.000.000đ/đêm.</li><li>Phòng VIP 2: 2.000.000đ/đêm.</li><li>Phòng VIP 3: 1.500.000đ/đêm.</li><li>Phòng VIP 4: 1.500.000đ/đêm.</li><li>Phòng VIP 5: 1.500.000đ/đêm.</li><li>Phòng đôi: 1.200.000đ/đêm.</li><li>Phòng thường 1: 600.000đ/đêm.</li><li>Phòng thường 2: 500.000đ/đêm.</li></ul>
', 'Công tử Bạc Liêu đốt tiền nấu trứng, tỏ ra mình giàu. Nghe danh Công tử Bạc Liêu chắc ai cũng từng nghe qua câu hát này. Ông là người có gia sản đồ sộ và ăn chơi đứng đầu bảng xếp hạng bấy giờ. Người ta bảo xứ Bạc Liêu trước đây 10 thửa [&hellip;]', 3507, 'post', '2019-02-01 13:43:25', '2023-04-23 12:50:38');

