INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (2820, 'Mẹ Nam Hải Bạc Liêu | CÁCH ĐI, SỰ TÍCH và sự LINH THIÊNG', 'me-nam-hai', '
<p>Mẹ Nam Hải là một tượng Quan Thế Âm Bồ Tát nằm ở tỉnh Bạc Liêu. Ngoài Miếu bà chúa Xứ thì nơi đây có lượng tín đồ hành hương đông đảo nhất. Hàng năm nó thu hút hàng trăm người về đây hành hương. Đặc biệt, nơi đây có pho tượng mẹ Nam Hải cao 11m, là công trình tượng phật Bà lớn nhất tỉnh Bạc Liêu. Đầu tiên, ta tìm hiểu về nguồn gốc của mẹ Nam Hải nhé!</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="960" height="720" src="https://media.huynhhieutravel.com/chùa-mẹ-nam-hải.jpg" alt="Chùa mẹ Nam Hải" class="wp-image-3370" srcset="https://media.huynhhieutravel.com/chùa-mẹ-nam-hải.jpg 960w, https://media.huynhhieutravel.com/chùa-mẹ-nam-hải-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption>Chùa mẹ Nam Hải</figcaption></figure>



<h2 class="wp-block-heading">Nguồn gốc mẹ Nam Hải</h2>



<p>Ban đầu, chùa mẹ Nam Hải ở Bạc Liêu là một căn nhà lá đơn sơ thờ phụng Quan Thế Âm Bồ Tát. Nó nằm ở một khu đất nhỏ ven biển, với xung quanh là bùn lầy và những rừng cây mắm, đước. Tương truyền ngôi chùa này lập nên để cầu an cho những người đi biển. Mong Phật bà phù hộ người dân đánh bắt xa bờ về nhà an toàn.</p>



<p>Đến năm 1973, Hòa thượng <a rel="noreferrer noopener nofollow" aria-label="Thích Trí Đức  (mở trong tab mới)" href="https://giacngo.vn/lichsu/2015/12/06/1FF04B/" target="_blank">Thích Trí Đức </a>đến đây, nhận ra sự linh thiêng thần thành nơi này nên đã cho xây dựng thành ngôi chùa khang trang hơn. Hòa thượng đã cho xây một Quan Thế Âm Bộ Tát cao 11m (Chưa tính phần bệ tượng) với tầm nhìn ra biển. Tượng xây trong 2 năm, đến năm 1975 thì hoàn thành.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="960" height="720" src="https://media.huynhhieutravel.com/du-khách-viếng-mẹ-nam-hải-bạc-liêu.jpg" alt="Du khách viếng mẹ Nam Hải Bạc Liêu" class="wp-image-3371" srcset="https://media.huynhhieutravel.com/du-khách-viếng-mẹ-nam-hải-bạc-liêu.jpg 960w, https://media.huynhhieutravel.com/du-khách-viếng-mẹ-nam-hải-bạc-liêu-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption>Du khách viếng chùa ở Bạc Liêu</figcaption></figure>



<h3 class="wp-block-heading">Lịch sử</h3>



<p>Lúc mới xây dựng lên, tượng đài đặt sát mé biển. Mắt tượng Phật bà nhìn ra xa về hướng biển để dõi theo những người đánh bắt xa bờ. Theo như các người dân hành hương trước đây kể lại, mỗi khi thủy triều lên, tượng Phật bà bị nước biển ngập tràn cả lên cả bệ đá. Nhưng sau nhiều năm bồi đắp thiên nhiên, vị trí chùa ở Bạc Liêu đã dời vào trong hơn vài km.</p>



<p>Đến năm 2004, chính quyền địa phương cấp phép cho việc mở rộng chùa lớn thêm. Người dân thập phương đến cúng viếng chùa mẹ Nam Hải đã quyên góp tiền mở rộng chùa thêm. Ước tính tổng cộng số tiền quyên góp là 5 tỷ đồng. </p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="960" height="720" src="https://media.huynhhieutravel.com/mẹ-nam-hải.jpg" alt="Mẹ Nam Hải" class="wp-image-3372" srcset="https://media.huynhhieutravel.com/mẹ-nam-hải.jpg 960w, https://media.huynhhieutravel.com/mẹ-nam-hải-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption>Mẹ Nam Hải</figcaption></figure>



<p>Nhờ vậy, nhiều hạng mục công trình đã khởi công và đến nay đã hoàn thành. Lúc ấy, chùa đã được mở rộng hơn 25.000m2 so với ngôi chùa đơn sơ trên mảnh đất nhỏ như trước đây.</p>



<p>Từ cổng tam quan, chánh điện, điện Thiên Thủ, điện Địa Tạng, nhà các nhà sư ở, phòng đã khách. Đến những hạng mục như nhà vệ sinh, các ghế đá và mái che cho khách thập phương viếng bà nghỉ tạm hay cả bãi giữ xe miễn phí.</p>



<p>Tuy vậy, hiện nay nhiều hạng mục vẫn đang hoàn thiền dần chứ chưa hoàn chỉnh hoàn toàn.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="946" height="710" src="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải1.jpg" alt="Tượng quan âm ở mẹ Nam Hải Bạc Liêu" class="wp-image-3373" srcset="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải1.jpg 946w, https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải1-768x576.jpg 768w" sizes="(max-width: 946px) 100vw, 946px" /><figcaption>Tượng quan âm ở Bạc Liêu</figcaption></figure>



<h3 class="wp-block-heading">Tượng Phật mẹ Quan Âm Nam Hải</h3>



<p>Tượng Phật mẹ Quan Âm Nam Hải có chiều cao 11m, mặt hướng về hướng Đông. Tượng Phật mẹ Nam Hải hướng mặt ra biển Đông với sự từ bi cầu an lành cho những người ngư dân đánh bắt xa bờ ngoài biển khơi.</p>



<p>Đặc biệt, xung quanh bệ đá đặt tượng đức mẹ Nam Hải Bạc Liêu là những nhan đèn nghi ngút của người dân cúng bái. Mọi người sẽ đặt đồ cúng viếng: nhang, trái cây hoa quả, tiền vàng, bánh trái,&#8230; để cúng viếng. Sau khi đặt đồ cúng sẽ là những lời cầu khấn thành tâm mong người phú hộ.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="946" height="709" src="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải2.jpg" alt="Tượng mẹ Quan Âm Nam Hải" class="wp-image-3374" srcset="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải2.jpg 946w, https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải2-768x576.jpg 768w" sizes="(max-width: 946px) 100vw, 946px" /><figcaption>Tượng mẹ Quan Âm Nam Hải</figcaption></figure>



<h3 class="wp-block-heading">Lễ hội</h3>



<p>Lễ hội Quán Âm Nam Hải là lễ hội được tổ chức thường niên vào ngày 22 đến ngày 23 tháng 3 âm lịch hàng năm. Đây là một trong những lễ hội Phật giáo lớn nhất ở Bạc Liêu và miền Tây Nam bộ. Lễ hội này đã được hội Phật giáo Việt Nam công nhận là một lễ hội chính thức của Phật giáo Việt Nam.</p>



<p>Nội dung lễ cúng mẹ Nam Hải thường là: Lễ cầu quốc thái dân an, văn khấn sóng yên biển lặng, văn khấn cúng anh hùng liệt sĩ, thỉnh thánh, lễ cầu ăn cầu siêu vong hồn, phật tử dân hương cúng bái, lễ thuyết pháp&#8230; Thông thường sau phần lễ hội sẽ là lễ cơm chay và tổ chức hát bội, văn nghệ phục vụ bà con tín đồ. </p>



<p>Ngoài ra, vào những dịp lễ rằm lớn như Trung thu, Vu lan, rằm tháng giêng,&#8230; ở đây đều tổ chức các lễ lớn để cúng bái. Đây cũng là những dịp tụ tập đông đảo khách hàng hương và tín đồ lễ mẹ nhiều nhất.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="960" height="720" src="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải3.jpg" alt="Một trong bức tượng mẹ Quan Âm Nam Hải Bạc Liêu" class="wp-image-3375" srcset="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải3.jpg 960w, https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải3-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption>Một trong bức tượng mẹ Quan Âm Nam Hải Bạc Liêu</figcaption></figure>



<h2 class="wp-block-heading">Mẹ Nam Hải ở đâu</h2>



<p>Mẹ Nam Hải có khá nhiều công trình mang tên gọi tương tự ở một số tỉnh thành khác như Cà Mau, Hậu Giang,.. Nhưng địa chỉ chính thức và nổi tiếng nhất là ở <a rel="noreferrer noopener" aria-label="Bạc Liêu (mở trong tab mới)" href="https://vi.wikipedia.org/wiki/B%E1%BA%A1c_Li%C3%AAu" target="_blank">Bạc Liêu</a>.</p>



<p>Nơi đây có lịch sử lâu đời, nhưng không có ghi chép rõ ràng về ngày khai chùa. Chỉ biết trước đây đã có tượng quan âm được xây đơn giản bởi những người thân ngư dân ra khơi xa đánh bắt. Đến năm 1973 nó mới được chính thức xây dựng một ngôi chùa đúng nghĩa.</p>



<p>Tham khảo du lịch Bạc Liêu với những điểm du lịch, review và món ăn hấp dẫn tại đây: <a href="https://huynhhieutravel.com/du-lich-bac-lieu">https://huynhhieutravel.com/du-lich-bac-lieu</a></p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="960" height="720" src="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải4.jpg" alt="Tượng đức mẹ Nam Hải Bạc Liêu" class="wp-image-3376" srcset="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải4.jpg 960w, https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải4-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption>Tượng đức quan âm ở Bạc Liêu</figcaption></figure>



<h3 class="wp-block-heading">Địa chỉ</h3>



<p>Địa chỉ: Đường Đê Biển, Phường Nhà Mát, tỉnh Bạc Liêu.</p>



<figure><iframe src="https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15753.490002292798!2d105.72824156148783!3d9.210938500801088!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x3c357ba81ce6fcf0!2sBuddha+Temple+Ba+Nam+Hai!5e0!3m2!1sen!2s!4v1545736470602" width="600" height="450" allowfullscreen=""></iframe></figure>



<h3 class="wp-block-heading">Cách đi</h3>



<p>Đường đến mẹ Nam Hải khá dễ đi, đa phần là đường quốc lộ lớn. Tuy vẫn có một số công trình đường đang xây nhưng tương đối ổn.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="960" height="720" src="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải5.jpg" alt="Hình ảnh mẹ Nam Hải Bạc Liêu" class="wp-image-3377" srcset="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải5.jpg 960w, https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải5-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption>Hình ảnh tượng Phật ở Bạc Liêu</figcaption></figure>



<h4 class="wp-block-heading">Hướng dẫn đi mẹ Nam Hải Bạc Liêu từ Hà Nội, Đà Nẵng</h4>



<p>Nếu bạn ở Hà Nội hay Đà Nẵng, những tỉnh thành xa thì phương tiện di chuyển tốt nhất chính là máy bay. Hiện chưa có tuyến bay thẳng đến Bạc Liêu nhưng bạn có thể bay đến tỉnh gần nhất là Cần Thơ.</p>



<p>Bạn có thể chọn các hãng bay Vietjet Air, Vietnam Airlines, Jetstar Airways để bay. Bạn có thể chọn hãng bay Vietjet Air với kinh phí bay thấp. Bạn có thể lựa chọn vé khuyến mãi 0 đồng nếu săn được hoặc đặt khoảng 2 &#8211; 3 tháng trước ngày bay thì giá sẽ rẻ nhất. Giá vé tầm 700.000 &#8211; 1.500.000 tuỳ vào đợt khuyến mãi và giá vé.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="960" height="720" src="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải6.jpg" alt="Một trong bức tượng bà mẹ Nam Hải" class="wp-image-3378" srcset="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải6.jpg 960w, https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải6-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption>Một trong bức tượng Quan âm</figcaption></figure>



<h4 class="wp-block-heading">Hướng dẫn đi mẹ Nam Hải Bạc Liêu từ Sài Gòn (TP. Hồ Chí Minh)</h4>



<p>Nếu di chuyển từ Sài Gòn bạn có thể lựa chọn các hãng xe bus uy tín như Phương Trang, Thành Bưởi để di chuyển. Ưu điểm của hai hãng xe này ngoài uy tín và chất lượng tốt thì còn có dịch vụ trung chuyển. Bạn có thể lựa chọn dịch vụ trung chuyển của hai hãng này. Dịch vụ trung chuyển với bán kính 5 &#8211; 10 km từ nội thành là dịch vụ giúp bạn tiết kiệm khá nhiều chi phí taxi. </p>



<p>Khoảng cách từ thành phố Bạc Liêu đến đây khoảng 12 km. Nếu bạn đi trung chuyển thì sẽ mất khoảng phí taxi khá nhỏ để di chuyển từ điểm đó đến đây.</p>



<p>Ngoài ra, nếu muốn di chuyển đi chơi nhiều hơn thì bạn có thể thuê xe máy ở khách sạn trung tâm thành phố Bạc Liêu. Giá thuê xe máy: 100.000 &#8211; 120.000đ/ngày.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="960" height="720" src="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải7.jpg" alt="Tượng Phật mẹ Nam Hải" class="wp-image-3379" srcset="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải7.jpg 960w, https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải7-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption>Tượng Phật</figcaption></figure>



<h4 class="wp-block-heading">Hướng dẫn đi mẹ Nam Hải Bạc Liêu từ Cần Thơ</h4>



<p>Bạn sẽ có hai cách lựa chọn di chuyển từ thành phố Cần Thơ đi mẹ Nam Hải Bạc Liêu. Bạn có thể sử dụng phương tiện cá nhân là ô tô hoặc xe máy di chuyển hoặc đi xe bus Phương Trang hoặc Thành Bưởi đến trung tâm thành phố Bạc Liêu.</p>



<p>Nếu chọn phương tiện cá nhân bạn sẽ đi theo đường quốc lộ ngang qua thành phố Sóc Trăng. Bạn có thể mất khoảng 4 &#8211; 5 tiếng cho hành trình hơn 120 km đến chùa ở Bạc Liêu. </p>



<p>Đường khá dễ đi vì đa phần là quốc lộ tuy có một số đoạn khá nhiều ổ gà, ổ voi. Lợi thế nữa là bạn có thể dừng chân bất kỳ đâu để tham quan, khám phá từ Sóc Trăng đến Bạc Liêu.</p>



<p>Kinh nghiệm, địa điểm du lịch và review Cần Thơ tại đây: <a href="https://huynhhieutravel.com/du-lich-can-tho">https://huynhhieutravel.com/du-lich-can-tho</a></p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="960" height="720" src="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải8.jpg" alt="Hình tượng Phật mẹ Nam Hải" class="wp-image-3380" srcset="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải8.jpg 960w, https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải8-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption>Hình tượng Phật</figcaption></figure>



<p>Nếu chọn phương tiện là xe bus bạn sẽ mất khoảng 3 tiếng rưỡi đến 4 tiếng di chuyển. Bạn sẽ tiết kiệm công sức rất nhiều cho việc di chuyển. Bạn có thể ngủ một giấc khi thức là đã gần đến nơi. Bạn sẽ mất phí di chuyển đoạn đường 12 km từ bến xe trung tâm thành phố Bạc Liêu đến đây. </p>



<p>Mẹo đi mẹ Nam Hải từ thành phố Bạc Liêu là bạn nên tận dụng xe trung chuyển. Trung chuyển đến vị trí xa nhất mà nó đi được gần đây nhất rồi di chuyển bằng taxi hoặc xe ôm đến đó.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="960" height="720" src="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải9.jpg" alt="Một trong những bức tượng mẹ Nam Hải ở Bạc Liêu" class="wp-image-3381" srcset="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải9.jpg 960w, https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải9-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption>Một trong những bức tượng  ở Bạc Liêu</figcaption></figure>



<h2 class="wp-block-heading">Kiến trúc chùa mẹ Nam Hải</h2>



<p>Kiến trúc của chùa xây theo kiểu kiến trúc Phật giáo Bắc tông truyền thống. Nhưng vẫn giữ nét chính là chùa chỉ chuyên thờ mẹ Quan Thế Âm Bồ Tát Nam Hải. Chùa có điện Quan Âm, chánh điện, nơi các sư ở, phòng khách,&#8230; </p>



<p>Đặc biệt, chùa có một núi Quan Âm to lớn được các Phật tử gom góp tiền bạc xây dựng. Kinh phí lên đến hơn 100 tỷ đồng. Núi Quan Âm cao 45m, rộng 90m, ngang 45m.</p>



<p>Nhìn từ ngoài vào, tượng mẹ Nam Hải cao 11m nằm ở giữa khuôn viên. Phía bên phải là Điện Quan Âm xây dựng nét kiến trúc truyền thống. Bên trái là Điện Địa Tạng. Đi thẳng vào bên trong sẽ là khuôn viên rộng lớn với hàng chục tượng Phật Quan Âm cao bằng hình người hai bên.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="960" height="720" src="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải11.jpg" alt="Tượng mẹ Nam Hải từ bi" class="wp-image-3383" srcset="https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải11.jpg 960w, https://media.huynhhieutravel.com/tượng-mẹ-quan-âm-ở-Nam-Hải11-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption>Tượng mẹ từ bi</figcaption></figure>



<p>Kiến trúc chùa chủ yếu là xây bằng xi măng và gỗ. Tượng Phật Quan Âm lên đến hàng chục tượng với kiến trúc khác nhau. Tượng đôi khi đứng, ngồi, nằm với những hình dạng khác nhau nhưng vô cùng tinh xảo.</p>



